import { randomBytes } from 'node:crypto';
import { inspect } from 'node:util';
import { describe, expect, it } from 'vitest';
import {
  Keyring,
  SecretBox,
  SecretBoxError,
  confirmIdempotencyKey,
  conversationLockKey,
  type SealedCode,
  type SealedCodeBinding,
} from '@r4-adapters/identity-verification';

// SEC-S2: authenticated encryption of a captured code (synthetic keys generated by the test).

const CODE = '482913';
const key = () => randomBytes(32).toString('base64');
const K0 = key();
const K1 = key();
const BINDING: SealedCodeBinding = { responseId: 'r-1', expectationId: 'e-1', channel: 'synthetic', providerEventId: 'evt.0001' };
const box = (spec: string) => new SecretBox(Keyring.parse(spec));
const failure = (fn: () => unknown): SecretBoxError => {
  try {
    fn();
  } catch (error) {
    if (error instanceof SecretBoxError) return error;
    throw error;
  }
  throw new Error('expected a SecretBoxError');
};
const flip = (buffer: Buffer, index = 0): Buffer => {
  const copy = Buffer.from(buffer);
  copy[index] = (copy[index] ?? 0) ^ 0x01;
  return copy;
};

describe('keyring', () => {
  it('parses ordered keys: the first seals, every one opens', () => {
    const keyring = Keyring.parse(`k1:${K1}, k0:${K0}`);
    expect(keyring.currentKeyId).toBe('k1');
    expect(keyring.keyIds).toEqual(['k1', 'k0']);
  });

  it.each([
    ['empty', ''],
    ['no separator', K0],
    ['empty id', `:${K0}`],
    ['bad id', `K-0:${K0}`],
    ['short key', `k0:${randomBytes(16).toString('base64')}`],
    ['long key', `k0:${randomBytes(48).toString('base64')}`],
    ['duplicate id', `k0:${K0},k0:${K1}`],
  ])('refuses %s', (_name, spec) => {
    expect(failure(() => Keyring.parse(spec)).code).toBe('invalid_keyring');
  });

  it('never prints or serializes key material', () => {
    const keyring = Keyring.parse(`k1:${K1},k0:${K0}`);
    const secretBox = new SecretBox(keyring);
    const raw = [K0, K1, Buffer.from(K0, 'base64').toString('hex'), Buffer.from(K1, 'base64').toString('hex')];
    for (const rendered of [JSON.stringify(keyring), String(keyring), inspect(keyring), JSON.stringify(secretBox), inspect(secretBox), JSON.stringify({ keyring, secretBox })]) {
      for (const material of raw) expect(rendered).not.toContain(material);
    }
    expect(Object.keys(keyring)).toEqual([]);
    expect(JSON.parse(JSON.stringify(keyring))).toEqual({ keyIds: ['k1', 'k0'] });
  });
});

describe('seal and open', () => {
  it('round-trips a six-digit code and never stores it in clear', () => {
    const sealed = box(`k0:${K0}`).seal(CODE, BINDING);
    expect(sealed.keyId).toBe('k0');
    expect(sealed.iv).toHaveLength(12);
    expect(sealed.tag).toHaveLength(16);
    expect(sealed.ciphertext.toString('utf8')).not.toBe(CODE);
    expect(sealed.ciphertext.toString('hex')).not.toContain(Buffer.from(CODE).toString('hex'));
    expect(box(`k0:${K0}`).open(sealed, BINDING)).toBe(CODE);
  });

  it.each(['48291', '4829131', '48291a', ' 482913', '４８２９１３', ''])('refuses to seal anything but six ASCII digits: %j', (code) => {
    expect(failure(() => box(`k0:${K0}`).seal(code, BINDING)).code).toBe('invalid_code');
  });

  it('uses a fresh random IV for every record', () => {
    const secretBox = box(`k0:${K0}`);
    const seals = Array.from({ length: 500 }, () => secretBox.seal(CODE, BINDING));
    expect(new Set(seals.map((s) => s.iv.toString('hex'))).size).toBe(500);
    expect(new Set(seals.map((s) => s.ciphertext.toString('hex') + s.tag.toString('hex'))).size).toBe(500);
  });
});

describe('tampering is detected (decrypt_failed)', () => {
  const secretBox = box(`k0:${K0}`);
  const sealed = secretBox.seal(CODE, BINDING);
  const tampered: [string, SealedCode][] = [
    ['ciphertext', { ...sealed, ciphertext: flip(sealed.ciphertext) }],
    ['last ciphertext byte', { ...sealed, ciphertext: flip(sealed.ciphertext, sealed.ciphertext.length - 1) }],
    ['IV', { ...sealed, iv: flip(sealed.iv) }],
    ['tag', { ...sealed, tag: flip(sealed.tag, 15) }],
    ['truncated tag', { ...sealed, tag: sealed.tag.subarray(0, 12) }],
  ];
  it.each(tampered)('%s', (_name, bad) => {
    expect(failure(() => secretBox.open(bad, BINDING)).code).toBe('decrypt_failed');
  });

  it.each<[string, SealedCodeBinding]>([
    ['another response', { ...BINDING, responseId: 'r-2' }],
    ['another expectation', { ...BINDING, expectationId: 'e-2' }],
    ['another channel', { ...BINDING, channel: 'other' }],
    ['another provider event', { ...BINDING, providerEventId: 'evt.0002' }],
  ])('AAD bound to the response identity: %s', (_name, binding) => {
    expect(failure(() => secretBox.open(sealed, binding)).code).toBe('decrypt_failed');
  });
});

describe('rotation and unknown keys', () => {
  it('a rotated keyring opens codes sealed with the previous key and seals with the new one', () => {
    const old = box(`k0:${K0}`).seal(CODE, BINDING);
    const rotated = box(`k1:${K1},k0:${K0}`);
    expect(rotated.open(old, BINDING)).toBe(CODE);
    expect(rotated.seal(CODE, BINDING).keyId).toBe('k1');
  });

  it('a retired key no longer opens its codes (unknown_key)', () => {
    const old = box(`k0:${K0}`).seal(CODE, BINDING);
    expect(failure(() => box(`k1:${K1}`).open(old, BINDING)).code).toBe('unknown_key');
  });

  it('the same id with other material does not open (decrypt_failed)', () => {
    const old = box(`k0:${K0}`).seal(CODE, BINDING);
    expect(failure(() => box(`k0:${K1}`).open(old, BINDING)).code).toBe('decrypt_failed');
  });
});

describe('errors carry only a code', () => {
  it('no plaintext, ciphertext, key or AAD in a SecretBoxError', () => {
    const secretBox = box(`k0:${K0}`);
    const sealed = secretBox.seal(CODE, BINDING);
    const errors = [
      failure(() => secretBox.open({ ...sealed, tag: flip(sealed.tag) }, BINDING)),
      failure(() => box(`k1:${K1}`).open(sealed, BINDING)),
      failure(() => secretBox.seal('12345x', BINDING)),
    ];
    for (const error of errors) {
      const rendered = `${error.message} ${error.stack ?? ''} ${JSON.stringify(error)} ${inspect(error)}`;
      for (const secret of [CODE, K0, sealed.ciphertext.toString('hex'), sealed.ciphertext.toString('base64'), BINDING.providerEventId, '12345x']) {
        expect(rendered).not.toContain(secret);
      }
    }
  });
});

describe('deterministic identities (pinned for SEC-S3)', () => {
  it('conversationLockKey is a stable signed 64-bit key per conversation', () => {
    expect(conversationLockKey('synthetic', 'a'.repeat(64))).toBe('-5953355791175460834');
    expect(conversationLockKey('synthetic', 'b'.repeat(64))).toBe('-5445765409269626959');
  });

  it('confirmIdempotencyKey follows the CIA key grammar and is derived from the provider event', () => {
    const value = confirmIdempotencyKey('synthetic', 'evt.0001');
    expect(value).toBe('vr.433a2cce31c3821b49930c2ce3155ab3c8ec4ea392ab5799d8bdc37bae839ac9');
    expect(value).toMatch(/^[A-Za-z0-9._:-]{16,128}$/);
    expect(confirmIdempotencyKey('synthetic', 'evt.0002')).not.toBe(value);
  });
});
